/* ============================================================
   NOT A HUMAN — тема для Tavo
   Визуальный язык игры: ночь «через глазок», бирюзовый монохром,
   реплики на голых чёрных плашках, синий экран старого CRT
   и ромбики энергии, которые тают, пока персонаж думает.
   Нужен Advanced Rendering.
   ============================================================ */

/* ---------- Анимации ---------- */
@keyframes nah-flashlight {
  0%   { background-position: -45% 15%; }
  30%  { background-position: 55% 100%; }
  55%  { background-position: 140% 20%; }
  80%  { background-position: 30% 65%; }
  100% { background-position: -45% 15%; }
}

@keyframes nah-breathe {
  0%, 100% { transform: scale(1); }
  45%      { transform: scale(1.015, 1.028); }
}

@keyframes nah-photo-flash {
  0%, 94%, 100% { filter: grayscale(1) sepia(1) hue-rotate(130deg) saturate(1.6) contrast(1.4) brightness(0.9); }
  95% { filter: grayscale(1) brightness(2.8) contrast(0.6); }
  97% { filter: grayscale(1) sepia(1) hue-rotate(130deg) saturate(1.6) contrast(1.4) brightness(1.3); }
}

@keyframes nah-static {
  0%   { background-position: 0 0, 0 0; }
  20%  { background-position: -37px 19px, 0 0; }
  40%  { background-position: 52px -41px, 0 0; }
  60%  { background-position: -13px 66px, 0 0; }
  80%  { background-position: 71px 8px, 0 0; }
  100% { background-position: 0 0, 0 0; }
}

@keyframes nah-energy-drain {
  0%   { background-image: url("theme/assets/energy-5.png"); }
  16%  { background-image: url("theme/assets/energy-4.png"); }
  33%  { background-image: url("theme/assets/energy-3.png"); }
  50%  { background-image: url("theme/assets/energy-2.png"); }
  66%  { background-image: url("theme/assets/energy-1.png"); }
  83%  { background-image: url("theme/assets/energy-0.png"); }
  100% { background-image: url("theme/assets/energy-0.png"); }
}

/* ---------- Реплики: голые чёрные плашки, как в игре ---------- */
.tavo-bubble {
  border-radius: 0;
  border: none;
}

/* Персонаж — чёрная плашка, по ней ползёт луч фонарика */
.tavo-character-bubble {
  background-color: rgba(0, 0, 0, 0.93);
  background-image: radial-gradient(circle closest-side, rgba(170, 245, 232, 0.2), rgba(110, 224, 212, 0.07) 55%, rgba(0, 0, 0, 0) 100%);
  background-size: 200px 200px;
  background-repeat: no-repeat;
  background-position: -45% 15%;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.55);
  animation: nah-flashlight 12s ease-in-out infinite;
}

/* Пользователь — плашка варианта ответа */
.tavo-user-bubble {
  background-color: rgba(14, 21, 20, 0.95);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
}

.tavo-message-content {
  line-height: 1.6;
  letter-spacing: 0.01em;
}

.tavo-message-content::selection,
.tavo-message-content *::selection {
  background: #6fe0d4;
  color: #000;
}

/* Пока идёт генерация — его реплики медленно дышат */
:root:has(.tavo-composer-stop-icon) .tavo-character-bubble {
  animation:
    nah-flashlight 12s ease-in-out infinite,
    nah-breathe 3.4s ease-in-out infinite;
}

.tavo-message-divider {
  border: none;
  height: 1px;
  background: rgba(111, 224, 212, 0.2);
}

/* ---------- Имена и аватары ---------- */
.tavo-speaker-name {
  color: #6fe0d4;
  font-weight: 500;
  letter-spacing: 0.04em;
  opacity: 0.8;
}

/* Аватары — фотокарточки осмотра в светлой рамке */
.tavo-avatar {
  border-radius: 0;
  box-shadow: 0 0 0 3px #e8e4d8, 0 4px 12px rgba(0, 0, 0, 0.6);
}

/* Персонаж — ночной бирюзовый снимок, иногда со вспышкой */
.tavo-character-avatar,
.tavo-group-character-avatar {
  filter: grayscale(1) sepia(1) hue-rotate(130deg) saturate(1.6) contrast(1.4) brightness(0.9);
  animation: nah-photo-flash 9s linear infinite;
}

/* Вы — тёплый «домашний» снимок, как интерьеры днём */
.tavo-user-avatar,
.tavo-group-user-avatar {
  filter: sepia(0.35) contrast(1.1) saturate(0.85);
}

/* ---------- Рассуждения, вложения, тулбар ---------- */
.tavo-message-reasoning {
  background: rgba(0, 0, 0, 0.6);
  border-left: 2px solid rgba(111, 224, 212, 0.35);
  padding-left: 8px;
}

.tavo-message-reasoning > summary {
  color: #4fb5aa;
}

/* Вложения — как вставка-улика при осмотре */
.tavo-message-attachments {
  box-shadow: 0 0 0 4px #e8e4d8, 0 8px 20px rgba(0, 0, 0, 0.6);
}

.tavo-action-bar-button,
.tavo-action-bar-button-group {
  background-color: rgba(0, 0, 0, 0.85);
  border-radius: 0;
}

/* ---------- Ромбики энергии над полем ввода ---------- */
.tavo-composer {
  padding-top: 22px;
  background-image: url("theme/assets/energy-5.png");
  background-size: auto 13px;
  background-repeat: no-repeat;
  background-position: left 18px top 4px;
}

/* Пока персонаж генерирует — энергия тает */
:root:has(.tavo-composer-stop-icon) .tavo-composer {
  animation: nah-energy-drain 6s steps(1, end) infinite;
}

/* ---------- Поле ввода: синий экран старого телевизора ---------- */
.tavo-composer-shell {
  background-color: #1b33c8;
  background-image: repeating-linear-gradient(
    to bottom,
    rgba(255, 255, 255, 0.06) 0,
    rgba(255, 255, 255, 0.06) 1px,
    rgba(0, 0, 0, 0) 1px,
    rgba(0, 0, 0, 0) 3px
  );
  border: 6px solid #151515;
  border-radius: 16px / 22px;
  box-shadow:
    0 0 0 1px #2e2e2e,
    0 8px 18px rgba(0, 0, 0, 0.7),
    inset 0 0 26px rgba(0, 0, 30, 0.65),
    inset 0 0 2px rgba(255, 255, 255, 0.5);
}

/* Во время генерации экран заливает помехами */
:root:has(.tavo-composer-stop-icon) .tavo-composer-shell {
  background-image:
    url("theme/assets/static.png"),
    repeating-linear-gradient(
      to bottom,
      rgba(255, 255, 255, 0.06) 0,
      rgba(255, 255, 255, 0.06) 1px,
      rgba(0, 0, 0, 0) 1px,
      rgba(0, 0, 0, 0) 3px
    );
  background-size: 128px 128px, auto;
  animation: nah-static 0.5s steps(1, end) infinite;
}

.tavo-composer-input {
  color: #fff;
  caret-color: #fff;
}

.tavo-composer-input::placeholder {
  color: #a9b6ff;
}

.tavo-composer-send-icon,
.tavo-composer-add-icon,
.tavo-composer-voice-icon,
.tavo-composer-stop-icon {
  filter: brightness(0) invert(1);
}

/* ---------- Без движения для тех, кому надо ---------- */
@media (prefers-reduced-motion: reduce) {
  .tavo-character-bubble,
  :root:has(.tavo-composer-stop-icon) .tavo-character-bubble,
  .tavo-character-avatar,
  .tavo-group-character-avatar,
  :root:has(.tavo-composer-stop-icon) .tavo-composer,
  :root:has(.tavo-composer-stop-icon) .tavo-composer-shell {
    animation: none;
  }
}

/* ---------- Версия с надписями (Visitor Check) ---------- */
@keyframes nah-ticker {
  0%   { background-position: 0 2px, 0 0, 0 0; }
  20%  { background-position: calc(-0.2 * 371px) 2px, 0 0, 0 0; }
  40%  { background-position: calc(-0.4 * 371px) 2px, 0 0, 0 0; }
  60%  { background-position: calc(-0.6 * 371px) 2px, 0 0, 0 0; }
  80%  { background-position: calc(-0.8 * 371px) 2px, 0 0, 0 0; }
  100% { background-position: calc(-1 * 371px) 2px, 0 0, 0 0; }
}

.tavo-message-reasoning > summary::after {
  content: "  — examining the guest";
  opacity: 0.6;
  font-style: italic;
}

/* Во время генерации по экрану бежит экстренное вещание */
:root:has(.tavo-composer-stop-icon) .tavo-composer-shell {
  background-image:
    url("theme/assets/ticker.png"),
    url("theme/assets/static.png"),
    repeating-linear-gradient(
      to bottom,
      rgba(255, 255, 255, 0.06) 0,
      rgba(255, 255, 255, 0.06) 1px,
      rgba(0, 0, 0, 0) 1px,
      rgba(0, 0, 0, 0) 3px
    );
  background-size: 371px 10px, 128px 128px, auto;
  background-repeat: repeat-x, repeat, repeat;
  animation: nah-ticker 9s linear infinite;
}
